[metadata] {"type": "create", "filePath": "/app/output/css/styles.css", "content": "/* WellStream Platform — Shared Styles */
:root {
  --navy-deep: #0D1B2A;
  --navy-dark: #15295A;
  --navy-mid: #1B2838;
  --navy-card: #1E3044;
  --navy-border: #243447;
  --gray-dark: #3C424B;
  --gray-mid: #5A6570;
  --gray-light: #8899AA;
  --text-primary: #E0E6ED;
  --text-secondary: #8899AA;
  --text-muted: #5A6570;
  --teal: #00B4D8;
  --teal-hover: #0096B4;
  --blue: #0077B6;
  --blue-hover: #006099;
  --green: #6CC24A;
  --green-hover: #5AAB3A;
  --white: #FFFFFF;
  --overlay: rgba(13, 27, 42, 0.7);
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --shadow-sm: 0 2px 8px rgba(0,0,0,0.3);
  --shadow-md: 0 4px 20px rgba(0,0,0,0.4);
  --shadow-lg: 0 8px 40px rgba(0,0,0,0.5);
  --font: 'Inter', 'Segoe UI', system-ui, -apple-system, sans-serif;
  --max-width: 1200px;
  --header-h: 72px;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; font-size: 16px; }

body {
  font-family: var(--font);
  background: var(--navy-deep);
  color: var(--text-primary);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  min-height: 100vh;
}

a { color: var(--teal); text-decoration: none; transition: color 0.2s; }
a:hover { color: var(--teal-hover); }

img { max-width: 100%; display: block; }

.container { max-width: var(--max-width); margin: 0 auto; padding: 0 24px; }

/* ========== HEADER / NAVIGATION ========== */
.site-header {
  position: fixed; top: 0; left: 0; right: 0; z-index: 1000;
  background: rgba(13, 27, 42, 0.92);
  backdrop-filter: blur(16px);
  border-bottom: 1px solid var(--navy-border);
  height: var(--header-h);
}
.header-inner {
  display: flex; align-items: center; justify-content: space-between;
  max-width: var(--max-width); margin: 0 auto; padding: 0 24px; height: 100%;
}
.logo {
  display: flex; align-items: center; gap: 10px;
  font-size: 1.35rem; font-weight: 700; color: var(--white);
}
.logo svg { width: 36px; height: 36px; }
.nav-main { display: flex; align-items: center; gap: 28px; list-style: none; }
.nav-main a { color: var(--text-secondary); font-size: 0.9rem; font-weight: 500; transition: color 0.2s; }
.nav-main a:hover, .nav-main a.active { color: var(--white); }

/* Dropdown */
.nav-dropdown { position: relative; }
.nav-dropdown-toggle {
  display: flex; align-items: center; gap: 4px; cursor: pointer;
  background: none; border: none; color: var(--text-secondary);
  font-size: 0.9rem; font-weight: 500; font-family: var(--font);
  padding: 0; transition: color 0.2s;
}
.nav-dropdown-toggle:hover, .nav-dropdown-toggle.open { color: var(--white); }
.nav-dropdown-toggle svg { width: 14px; height: 14px; transition: transform 0.2s; }
.nav-dropdown-toggle.open svg { transform: rotate(180deg); }
.nav-dropdown-menu {
  display: none; position: absolute; top: 100%; left: 50%; transform: translateX(-50%);
  background: var(--navy-mid); border: 1px solid var(--navy-border);
  border-radius: var(--radius-md); padding: 8px 0; min-width: 200px;
  box-shadow: var(--shadow-lg); margin-top: 8px;
}
.nav-dropdown-menu.open { display: block; }
.nav-dropdown-menu a {
  display: block; padding: 10px 20px; color: var(--text-secondary);
  font-size: 0.88rem; transition: all 0.15s;
}
.nav-dropdown-menu a:hover { background: rgba(255,255,255,0.05); color: var(--white); }

/* CTA Button */
.btn {
  display: inline-flex; align-items: center; justify-content: center;
  padding: 10px 24px; border-radius: var(--radius-sm); font-weight: 600;
  font-size: 0.9rem; font-family: var(--font); cursor: pointer;
  transition: all 0.2s; border: none; gap: 8px; white-space: nowrap;
}
.btn-primary { background: var(--teal); color: var(--navy-deep); }
.btn-primary:hover { background: var(--teal-hover); color: var(--navy-deep); }
.btn-secondary { background: transparent; border: 1.5px solid var(--teal); color: var(--teal); }
.btn-secondary:hover { background: var(--teal); color: var(--navy-deep); }
.btn-green { background: var(--green); color: var(--navy-deep); }
.btn-green:hover { background: var(--green-hover); color: var(--navy-deep); }
.btn-lg { padding: 14px 32px; font-size: 1rem; }
.btn-sm { padding: 6px 16px; font-size: 0.82rem; }

/* Mobile nav toggle */
.nav-toggle { display: none; background: none; border: none; cursor: pointer; padding: 8px; }
.nav-toggle span { display: block; width: 24px; height: 2px; background: var(--white); margin: 5px 0; transition: all 0.3s; border-radius: 2px; }

/* ========== FOOTER ========== */
.site-footer {
  background: var(--navy-mid); border-top: 1px solid var(--navy-border);
  padding: 60px 0 30px;
}
.footer-grid {
  display: grid; grid-template-columns: repeat(5, 1fr); gap: 40px;
}
.footer-col h4 {
  color: var(--white); font-size: 0.85rem; text-transform: uppercase;
  letter-spacing: 0.06em; margin-bottom: 18px;
}
.footer-col a {
  display: block; color: var(--text-secondary); font-size: 0.88rem;
  padding: 4px 0; transition: color 0.15s;
}
.footer-col a:hover { color: var(--teal); }
.footer-bottom {
  margin-top: 50px; padding-top: 24px; border-top: 1px solid var(--navy-border);
  display: flex; justify-content: space-between; align-items: center;
  font-size: 0.82rem; color: var(--text-muted);
}
.footer-login-links { display: flex; gap: 20px; }
.footer-login-links a { color: var(--text-secondary); font-size: 0.82rem; }
.footer-login-links a:hover { color: var(--teal); }

/* ========== HERO ========== */
.hero {
  padding: 120px 0 80px;
  text-align: center;
  position: relative;
  overflow: hidden;
}
.hero::before {
  content: ''; position: absolute; top: 0; left: 0; right: 0; bottom: 0;
  background: radial-gradient(ellipse at 50% 0%, rgba(0,180,216,0.08) 0%, transparent 60%);
}
.hero-label {
  font-size: 0.8rem; text-transform: uppercase; letter-spacing: 0.15em;
  color: var(--teal); margin-bottom: 20px; font-weight: 600;
}
.hero h1 {
  font-size: clamp(2rem, 4vw, 3.2rem); font-weight: 800;
  line-height: 1.15; color: var(--white); margin-bottom: 20px;
  max-width: 900px; margin-left: auto; margin-right: auto;
}
.hero p {
  font-size: 1.1rem; color: var(--text-secondary); max-width: 640px;
  margin: 0 auto 32px; line-height: 1.6;
}
.hero-actions { display: flex; gap: 14px; justify-content: center; flex-wrap: wrap; }
.hero-inner { position: relative; z-index: 1; }

/* Page hero (smaller) */
.page-hero {
  padding: 100px 0 50px; text-align: center;
  background: radial-gradient(ellipse at 50% 0%, rgba(0,180,216,0.06) 0%, transparent 60%);
}
.page-hero h1 { font-size: clamp(1.6rem, 3vw, 2.4rem); font-weight: 800; color: var(--white); }
.page-hero p { font-size: 1.05rem; color: var(--text-secondary); max-width: 600px; margin: 12px auto 0; }

/* ========== SECTION COMMONS ========== */
.section { padding: 80px 0; }
.section-dark { background: var(--navy-mid); }
.section-label {
  font-size: 0.78rem; text-transform: uppercase; letter-spacing: 0.14em;
  color: var(--teal); font-weight: 600; margin-bottom: 12px;
}
.section-heading {
  font-size: clamp(1.5rem, 2.5vw, 2rem); font-weight: 700;
  color: var(--white); margin-bottom: 14px;
}
.section-desc {
  font-size: 1rem; color: var(--text-secondary); max-width: 680px;
  margin-bottom: 48px; line-height: 1.6;
}
.text-center { text-align: center; }
.mx-auto { margin-left: auto; margin-right: auto; }

/* ========== USE CASES GRID ========== */
.use-cases-grid {
  display: grid; grid-template-columns: repeat(3, 1fr); gap: 20px;
}
.use-case-card {
  background: var(--navy-card); border: 1px solid var(--navy-border);
  border-radius: var(--radius-md); padding: 32px 24px;
  transition: border-color 0.25s, transform 0.25s, box-shadow 0.25s;
  cursor: pointer;
}
.use-case-card:hover {
  border-color: var(--teal); transform: translateY(-3px);
  box-shadow: var(--shadow-md);
}
.use-case-card .icon {
  width: 48px; height: 48px; border-radius: var(--radius-sm);
  background: rgba(0,180,216,0.12); display: flex; align-items: center;
  justify-content: center; margin-bottom: 18px;
}
.use-case-card .icon svg { width: 24px; height: 24px; color: var(--teal); }
.use-case-card h3 { font-size: 1.05rem; color: var(--white); margin-bottom: 8px; font-weight: 600; }
.use-case-card p { font-size: 0.88rem; color: var(--text-secondary); line-height: 1.5; }

/* ========== INDUSTRY TABS ========== */
.industry-tabs { display: flex; gap: 4px; flex-wrap: wrap; margin-bottom: 36px; }
.industry-tab {
  padding: 10px 22px; border-radius: 50px; font-size: 0.85rem;
  font-weight: 500; cursor: pointer; border: 1.5px solid var(--navy-border);
  background: transparent; color: var(--text-secondary);
  transition: all 0.2s; font-family: var(--font);
}
.industry-tab:hover { border-color: var(--gray-light); color: var(--white); }
.industry-tab.active {
  background: var(--teal); border-color: var(--teal); color: var(--navy-deep);
}
.industry-content { display: none; }
.industry-content.active { display: block; }

/* ========== FEATURED PRODUCT BANNER ========== */
.featured-banner {
  background: linear-gradient(135deg, var(--navy-dark) 0%, var(--navy-card) 100%);
  border: 1px solid var(--navy-border); border-radius: var(--radius-lg);
  padding: 40px 48px; display: flex; align-items: center;
  justify-content: space-between; gap: 24px;
}
.featured-banner .product-tag { font-size: 0.78rem; text-transform: uppercase; letter-spacing: 0.1em; color: var(--green); font-weight: 600; }
.featured-banner h3 { font-size: 1.4rem; color: var(--white); margin: 6px 0; }
.featured-banner p { font-size: 0.95rem; color: var(--text-secondary); }

/* ========== PLATFORM ECOSYSTEM DIAGRAM ========== */
.ecosystem-diagram {
  display: flex; align-items: center; justify-content: center; gap: 32px;
  padding: 40px 0; flex-wrap: wrap;
}
.eco-pillar {
  background: var(--navy-card); border: 1px solid var(--navy-border);
  border-radius: var(--radius-lg); padding: 36px 28px; text-align: center;
  flex: 1; min-width: 240px; max-width: 320px;
  transition: border-color 0.3s, transform 0.3s;
}
.eco-pillar:hover { border-color: var(--teal); transform: translateY(-3px); }
.eco-pillar .pillar-icon { margin-bottom: 16px; }
.eco-pillar .pillar-icon svg { width: 52px; height: 52px; color: var(--teal); }
.eco-pillar h4 { font-size: 1.1rem; color: var(--white); margin-bottom: 8px; }
.eco-pillar p { font-size: 0.88rem; color: var(--text-secondary); line-height: 1.5; }
.eco-connector { display: flex; align-items: center; color: var(--teal); opacity: 0.5; }
.eco-connector svg { width: 32px; height: 32px; }

/* ========== CULTURE / CTA SECTIONS ========== */
.culture-cta, .renewables-cta {
  display: grid; grid-template-columns: 1fr 1fr; gap: 48px; align-items: center;
}
.culture-cta.reversed { direction: rtl; }
.culture-cta.reversed > * { direction: ltr; }
.cta-content h2 { font-size: 1.8rem; font-weight: 700; color: var(--white); margin-bottom: 16px; }
.cta-content p { font-size: 1rem; color: var(--text-secondary); margin-bottom: 24px; line-height: 1.6; }
.cta-visual {
  background: var(--navy-card); border: 1px solid var(--navy-border);
  border-radius: var(--radius-lg); height: 300px; display: flex;
  align-items: center; justify-content: center;
}

/* ========== PLATFORM BENEFITS ========== */
.benefits-grid {
  display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 20px;
}
.benefit-card {
  background: var(--navy-card); border: 1px solid var(--navy-border);
  border-radius: var(--radius-md); padding: 28px 22px; text-align: center;
  transition: border-color 0.25s;
}
.benefit-card:hover { border-color: var(--teal); }
.benefit-card .benefit-icon { margin-bottom: 14px; }
.benefit-card .benefit-icon svg { width: 40px; height: 40px; color: var(--teal); }
.benefit-card h4 { font-size: 1.05rem; color: var(--white); margin-bottom: 8px; }
.benefit-card p { font-size: 0.85rem; color: var(--text-secondary); line-height: 1.5; }

/* ========== STATS CIRCLES ========== */
.stats-row {
  display: flex; justify-content: center; gap: 48px; flex-wrap: wrap;
}
.stat-circle {
  width: 180px; height: 180px; border-radius: 50%;
  background: var(--navy-card); border: 3px solid var(--navy-border);
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  text-align: center; transition: border-color 0.3s; position: relative;
}
.stat-circle::after {
  content: ''; position: absolute; inset: -6px; border-radius: 50%;
  border: 2px solid var(--teal); opacity: 0; transition: opacity 0.3s;
}
.stat-circle:hover { border-color: var(--teal); }
.stat-circle:hover::after { opacity: 0.3; }
.stat-circle .stat-number {
  font-size: 2.4rem; font-weight: 800; color: var(--teal); line-height: 1;
}
.stat-circle .stat-label {
  font-size: 0.82rem; color: var(--text-secondary); margin-top: 6px;
  max-width: 120px; line-height: 1.3;
}

/* ========== IMPLEMENTATION TIMELINE ========== */
.timeline { max-width: 700px; margin: 0 auto; }
.timeline-item {
  margin-bottom: 32px; position: relative; padding-left: 32px;
}
.timeline-item::before {
  content: ''; position: absolute; left: 8px; top: 28px; bottom: -32px;
  width: 2px; background: var(--navy-border);
}
.timeline-item:last-child::before { display: none; }
.timeline-item .time-dot {
  position: absolute; left: 0; top: 4px; width: 18px; height: 18px;
  border-radius: 50%; background: var(--teal);
}
.timeline-item .time-header { display: flex; align-items: center; gap: 12px; margin-bottom: 6px; }
.timeline-item .time-label {
  font-size: 1.2rem; font-weight: 700; color: var(--teal);
}
.timeline-item .time-desc { font-size: 0.9rem; color: var(--text-secondary); margin-bottom: 10px; }
.progress-bar {
  height: 6px; background: var(--navy-border); border-radius: 3px; overflow: hidden;
}
.progress-bar .fill {
  height: 100%; background: linear-gradient(90deg, var(--teal), var(--green));
  border-radius: 3px; transition: width 1s ease;
}

/* ========== ACCORDION ========== */
.accordion { max-width: 800px; margin: 0 auto; }
.accordion-item {
  border: 1px solid var(--navy-border); border-radius: var(--radius-md);
  margin-bottom: 12px; overflow: hidden; background: var(--navy-card);
