.accordion-header {
  width: 100%; padding: 20px 24px; display: flex; align-items: center;
  justify-content: space-between; background: none; border: none;
  color: var(--white); font-size: 1.05rem; font-weight: 600;
  font-family: var(--font); cursor: pointer; text-align: left;
  transition: background 0.2s;
}
.accordion-header:hover { background: rgba(255,255,255,0.03); }
.accordion-header .accordion-icon {
  width: 24px; height: 24px; transition: transform 0.3s;
  color: var(--teal); flex-shrink: 0;
}
.accordion-header.open .accordion-icon { transform: rotate(180deg); }
.accordion-body {
